import {groupSlug,mountSpendingDetails} from './detail-view.mjs';
import {estimateSpending} from './spending-plan.mjs';
import {projectForecast,currentLedgerDate} from './projection.mjs';
import {projectMonthlySavings} from './monthly-savings.mjs';
import {compareTrends} from './trend-comparison.mjs';
import {addDays} from './engine.mjs';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);

export function mountInsights({getState,getModel,navigate}){
  const details=mountSpendingDetails({getState,navigate});
  let comparisonDraft={targetDate:null,diningReductionPercent:0,shoppingReductionPercent:0,excludedRenewalKeys:[]};
  function renderComparison(){
    if(!$('#trend-comparison'))$('#monthly-savings').insertAdjacentHTML('beforebegin','<section id="trend-comparison" class="content-panel insights-section"></section>');
    const state=getState(),panel=$('#trend-comparison');panel.hidden=state.mode==='example';if(panel.hidden)return;
    const earliest=state.plan.startDate,latest=addDays(earliest,179);
    if(!comparisonDraft.targetDate||comparisonDraft.targetDate<earliest||comparisonDraft.targetDate>latest)comparisonDraft.targetDate=getModel().endDate;
    const available=compareTrends(state,{...comparisonDraft,excludedRenewalKeys:[]});
    const known=new Set(available.candidates.map(c=>c.key));comparisonDraft.excludedRenewalKeys=comparisonDraft.excludedRenewalKeys.filter(k=>known.has(k));
    const initial=compareTrends(state,comparisonDraft);
    panel.innerHTML=`<h2>Where you could be</h2><p>Compare your current trend with changes you choose. This is a temporary projection, not a change to your spending plan.</p><div class="trend-controls"><label>Choose a date<input id="trend-target" type="date" min="${esc(earliest)}" max="${esc(latest)}" value="${esc(comparisonDraft.targetDate)}"></label><label>Reduce dining spending <output id="trend-dining-label">${comparisonDraft.diningReductionPercent}%</output><input id="trend-dining" type="range" min="0" max="100" step="5" value="${comparisonDraft.diningReductionPercent}"></label><label>Reduce shopping spending <output id="trend-shopping-label">${comparisonDraft.shoppingReductionPercent}%</output><input id="trend-shopping" type="range" min="0" max="100" step="5" value="${comparisonDraft.shoppingReductionPercent}"></label></div><details id="trend-renewals" class="trend-renewals"><summary>What if you stopped paying for a recurring charge?</summary><p>These are tentative renewal estimates. Selecting one only removes its estimated future charges from this comparison; it does not cancel a service.</p>${initial.candidates.map(c=>`<label><input type="checkbox" data-trend-renewal="${esc(c.key)}" ${comparisonDraft.excludedRenewalKeys.includes(c.key)?'checked':''}> ${esc(c.name)} · ${money(c.amount)} per estimated charge</label>`).join('')||'<p>No dated tentative charges are included in this baseline.</p>'}</details><button id="trend-reset" class="text-button" type="button">Reset changes</button><div id="trend-results" aria-live="polite"></div><p class="quiet-note">Dining and shopping reductions apply to separate routine categories. Future large purchases, undated renewals and unrecorded cash spending are not removed by these sliders and can reduce the result. Starting balances retain their recorded dates.</p>`;
    const update=()=>{
      comparisonDraft={targetDate:$('#trend-target').value,diningReductionPercent:Number($('#trend-dining').value),shoppingReductionPercent:Number($('#trend-shopping').value),excludedRenewalKeys:[...panel.querySelectorAll('[data-trend-renewal]:checked')].map(x=>x.dataset.trendRenewal)};
      $('#trend-dining-label').textContent=comparisonDraft.diningReductionPercent+'%';$('#trend-shopping-label').textContent=comparisonDraft.shoppingReductionPercent+'%';
      try{const r=compareTrends(getState(),comparisonDraft);$('#trend-results').innerHTML=`<div class="trend-outcomes"><div><span>At your current trend on ${esc(r.targetDate)}</span><strong>${money(r.baseline.ending)}</strong><p>Lowest funds before then: ${money(r.baseline.min)}</p></div><div><span>With your changes</span><strong>${money(r.changed.ending)}</strong><p>Lowest funds before then: ${money(r.changed.min)}</p></div><div><span>Difference over this period</span><strong class="positive">+${money(r.improvement)}</strong><p>Balances, bills and history stay unchanged.</p></div></div>`;}catch(error){$('#trend-results').innerHTML=`<p class="negative">${esc(error.message)}</p>`;}
    };
    $('#trend-target').onchange=update;$('#trend-dining').oninput=update;$('#trend-shopping').oninput=update;panel.querySelectorAll('[data-trend-renewal]').forEach(x=>x.onchange=update);
    $('#trend-reset').onclick=()=>{comparisonDraft={...comparisonDraft,diningReductionPercent:0,shoppingReductionPercent:0,excludedRenewalKeys:[]};renderComparison();};update();
  }
  function renderMonthlySavings(){
    if(!$('#monthly-savings'))$('#forecast-content .plan-strip').insertAdjacentHTML('beforebegin','<section id="monthly-savings" class="content-panel insights-section"></section>');
    const state=getState(),panel=$('#monthly-savings');panel.hidden=false;
    const projection=projectMonthlySavings(state);
    const monthName=value=>new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric'}).format(new Date(value+'-15T12:00:00'));
    panel.innerHTML=`<h2>Projected monthly savings</h2><p>Potential money left after expected costs, if your current trends continue. This does not move money into savings.</p><div class="table-scroll desktop-report"><table class="ledger-table monthly-savings-table"><thead><tr><th>Month</th><th>Expected income</th><th>Expected costs</th><th>Potential savings</th><th>Funds at month end</th></tr></thead><tbody>${projection.months.map(m=>`<tr><td><strong>${esc(monthName(m.month))}</strong><small>${esc(m.startDate)} – ${esc(m.endDate)}${m.partial?' · Partial month':''}</small><details id="month-breakdown-${esc(m.month)}"><summary>Cost breakdown</summary><p>Confirmed bills: ${money(m.confirmedBills)}<br>Tentative renewals: ${money(m.estimatedRecurring)}<br>Routine purchases: ${money(m.routine)}<br>Opening funds: ${money(m.openingBalance)}<br>Lowest expected funds: ${money(m.lowestBalance)}</p></details></td><td>${money(m.income)}</td><td>${money(m.expenses)}</td><td class="${m.netSavings<0?'negative':'positive'}"><strong>${money(m.netSavings)}</strong>${m.netSavings<0?'<small>Spending exceeds income</small>':''}</td><td>${money(m.endingBalance)}</td></tr>`).join('')}</tbody></table></div><div class="mobile-report-list">${projection.months.map(m=>`<details class="report-row" id="mobile-month-${esc(m.month)}"><summary><span><strong>${esc(monthName(m.month))}</strong><small>${m.partial?'Partial month · ':''}Potential savings</small></span><strong class="${m.netSavings<0?'negative':'positive'}">${money(m.netSavings)}</strong></summary><dl class="report-facts"><div><dt>Expected income</dt><dd>${money(m.income)}</dd></div><div><dt>Expected costs</dt><dd>${money(m.expenses)}</dd></div><div><dt>Funds at month end</dt><dd>${money(m.endingBalance)}</dd></div><div><dt>Lowest expected funds</dt><dd>${money(m.lowestBalance)}</dd></div><div><dt>Confirmed bills</dt><dd>${money(m.confirmedBills)}</dd></div><div><dt>Tentative renewals</dt><dd>${money(m.estimatedRecurring)}</dd></div><div><dt>Routine purchases</dt><dd>${money(m.routine)}</dd></div><div><dt>Opening funds</dt><dd>${money(m.openingBalance)}</dd></div></dl><p class="quiet-note">${esc(m.startDate)} – ${esc(m.endDate)}${m.netSavings<0?' · Spending exceeds income.':''}</p></details>`).join('')}</div><p class="quiet-note">Potential savings = that month’s projected income minus costs. Existing balances are counted only in funds at month end. Negative months carry forward. ${projection.truncated?'The final month is limited by the 180-day forecast horizon.':''}</p><p class="quiet-note">The first month starts at your balance snapshot, so it may show only the rest of the month. Estimates include confirmed bills and dated tentative renewals; unplanned bulk purchases, undated renewals and unmeasured cash spending can reduce these amounts.</p>`;
  }
  function categoryTable(e){
    const max=Math.max(1,...e.groups.map(g=>g.total));
    return `<div class="table-scroll"><table class="ledger-table insights-categories"><thead><tr><th>Where it went</th><th>Recorded</th><th>Routine / week</th></tr></thead><tbody>${e.groups.filter(g=>g.total>0).sort((a,b)=>b.total-a.total).map(g=>`<tr><td><button class="text-button" id="group-${groupSlug(g.name)}" data-spend-group="${esc(g.name)}">${esc(g.name)}</button><div class="bar-track"><div class="bar-fill" style="width:${Math.round(g.total/max*100)}%"></div></div></td><td>${money(g.total)}<small>${g.count} purchases</small></td><td>${money(g.routineWeekly)}</td></tr>`).join('')}</tbody></table></div><div id="spend-group-detail" aria-live="polite"></div>`;
  }
  function savings(e,compact=false){return `<h2>Ways to spend less</h2><p>Amounts come from your recorded spending. Try one change at a time; nothing here changes your plan.</p>${e.savings.slice(0,compact?2:20).map((s,i)=>`<div class="saving-row"><div><h3>${esc(s.name)}</h3><p>${esc(s.basis)}</p><p class="quiet-note">${esc(s.description)}</p></div><div>${s.kind==='scenario'?`<strong>${money(s.weekly)}/week</strong><p>About ${money(s.monthly)}/month</p><button class="button small" data-saving="${i}">Try this reduction</button>`:`<strong>${money(s.observedWeekly||0)}/week recorded</strong><p>Savings depend on what you change.</p><a class="text-button" href="#bills">Review charges ↗</a>`}</div></div>`).join('')||'<p>Not enough recorded discretionary spending for a supported savings estimate yet.</p>'}<div class="saving-result" aria-live="polite"></div>`;}
  function bind(root,e){
    root.querySelectorAll('[data-spend-group]').forEach(button=>button.onclick=()=>{
      navigate('spending','categories',[groupSlug(button.dataset.spendGroup)]);
    });
    root.querySelectorAll('[data-saving]').forEach(button=>button.onclick=()=>{
      const suggestion=e.savings[Number(button.dataset.saving)],base=getModel();
      const projected=projectForecast(getState(),null,{dailyReduction:suggestion.weekly/7});
      root.querySelector('.saving-result').innerHTML=`<h3>If you ${esc(suggestion.name.toLowerCase())}</h3><p>Projected ending balance: <strong>${money(projected.ending)}</strong> (${money(projected.ending-base.ending)} more over this forecast). Lowest balance: <strong>${money(projected.min)}</strong> on ${esc(projected.minDate)}.</p><p class="quiet-note">Same paychecks, bills and estimated renewals. This is a temporary spending scenario; balances and history have not changed.</p>`;
    });
  }
  function renderForecast(){
    renderMonthlySavings();
    renderComparison();
    const state=getState(),p=state.plan,m=getModel(),e=estimateSpending(state.transactions,p,{ledgerAsOf:currentLedgerDate()});
    if(!$('#spending-plan'))$('#forecast-content .plan-strip').insertAdjacentHTML('beforebegin','<section id="spending-plan" class="content-panel"></section>');
    const panel=$('#spending-plan');panel.hidden=state.mode==='example'||!e;
    if(!$('#forecast-funds-warning'))$('#forecast-content').insertAdjacentHTML('afterbegin','<div id="forecast-funds-warning" class="info-note" hidden></div>');
    const warning=$('#forecast-funds-warning');warning.hidden=!p.forecastBasis?.incompleteFunds;if(!warning.hidden)warning.textContent='Balance limitation: '+p.forecastBasis.balanceNote;
    if(panel.hidden)return;
    const events=m.events.filter(x=>x.type==='bill'||x.type==='income').slice(0,10);
    panel.innerHTML=`<h2>Your usual spending, separate from big purchases</h2><p><strong>${money(m.routineDaily??p.dailySpend)}/day</strong> routine estimate · ${money(e.weeklyRoutine)}/week in observed routine purchases.</p><p>${money(e.oneOffTotal)} in large or irregular purchases is kept separate, rather than repeated every day. ${money(e.subscriptionTotal)} in recorded recurring charges is also separate.</p><p class="quiet-note">Based on ${esc(e.start)} to ${esc(e.end)} (${e.activeDays} days with records out of ${e.days}). Missing records do not prove no spending.</p><h3>Money coming in and likely costs</h3><p>${money(p.balance)} starting funds · ${money(m.income)} expected pay · ${money(m.confirmedBillsTotal??m.bills)} confirmed bills${m.estimatedRecurringTotal?` · ${money(m.estimatedRecurringTotal)} tentative renewals`:''}.</p><div class="table-scroll"><table class="ledger-table"><thead><tr><th>Date</th><th>What</th><th>Amount</th></tr></thead><tbody>${events.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.name)}${x.id.startsWith('estimated:')?' · unconfirmed':''}</td><td>${x.type==='income'?'+':'−'}${money(x.amount)}</td></tr>`).join('')}</tbody></table></div><p class="quiet-note">Tentative renewal dates use posted history and can move. Undated renewals, future bulk purchases and unmeasured cash spending need extra room; they are not guaranteed to be covered.</p>${p.forecastBasis?`<details id="balance-assumptions"><summary>Balances and assumptions</summary><p>${esc(p.forecastBasis.balanceNote)}</p><p>${esc(p.forecastBasis.cashNote)}</p></details>`:''}<a class="text-button" href="#spending">See the daily spending map and savings scenarios ↗</a>`;
  }
  function renderSpending(){
    const state=getState(),e=estimateSpending(state.transactions,state.plan,{ledgerAsOf:currentLedgerDate()}),content=$('#spending-content');
    $('#spending-period').closest('label').hidden=true;
    const toolbar=$('[data-workspace-toolbar=spending]');if(toolbar)toolbar.hidden=!e;
    if(!e){content.innerHTML=`<section class="content-panel spending-empty"><h2>${state.transactions.length?'Your records are here':'Build a picture of your spending'}</h2><p>${state.transactions.length?'You can review your recorded transactions now. Source-based routine spending analysis is not available for these records.':'Import a statement to start reviewing earlier purchases.'}</p><p>Routine-spending patterns need supported purchase history. Until then, your saved daily estimate is used in the forecast. Imports do not change your starting balance.</p><div class="button-row"><button class="button primary" type="button" id="spending-import">Import statement</button><a class="button" href="#transactions">Review transactions</a></div></section>`;$('#spending-import').onclick=()=>$('#import-csv').click();return;}
    content.innerHTML=`<div class="spend-topline report-summary"><div><span>Routine spending / day</span><strong>${money(e.daily)}</strong></div><div><span>Large purchases in this window</span><strong>${money(e.oneOffTotal)}</strong></div><div><span>Recurring charges recorded</span><strong>${money(e.subscriptionTotal)}</strong></div></div><p class="quiet-note">${esc(e.start)} – ${esc(e.end)} · ${e.activeDays} of ${e.days} days recorded. Account coverage is incomplete; cash spending is not measured.</p><section id="spending-categories" data-workspace-panel="spending:categories" data-workspace-essential class="content-panel"><h2 class="report-repeat-title">Spending categories</h2><p class="report-description">${esc(e.start)} – ${esc(e.end)}. Tap a category to see its purchases. Categories follow your rules.</p>${categoryTable(e)}</section><section id="spending-daily" data-workspace-panel="spending:daily" data-workspace-essential class="content-panel insights-section"><h2>Latest recorded daily activity</h2><p>${esc(e.start)} through ${esc(e.ledgerAsOf)}. Includes recorded bills as well as everyday purchases. Partial marks activity beyond the shared baseline window, where account coverage may be incomplete. Days without records are not assumed to be free.</p><div class="table-scroll daily-history desktop-report"><table class="ledger-table"><thead><tr><th>Date</th><th>Recorded</th><th>Routine</th><th>Large purchases</th><th>Recurring</th><th>Bills</th></tr></thead><tbody>${[...(e.recentDailyHistory||e.dailyHistory)].filter(d=>d.total>0).reverse().map(d=>`<tr><td>${esc(d.date)}${d.partialCoverage?" · Partial":""}</td><td>${money(d.total)}</td><td>${money(d.routine)}</td><td>${money(d.oneOff)}</td><td>${money(d.subscriptions)}</td><td>${money(d.bills||0)}</td></tr>`).join('')}</tbody></table></div><div class="mobile-report-list">${[...(e.recentDailyHistory||e.dailyHistory)].filter(d=>d.total>0).reverse().map(d=>`<details class="report-row" id="mobile-day-${esc(d.date)}"><summary><span><strong>${esc(d.date)}</strong><small>${d.partialCoverage?'Partial coverage':'Recorded spending'}</small></span><strong>${money(d.total)}</strong></summary><dl class="report-facts"><div><dt>Routine</dt><dd>${money(d.routine)}</dd></div><div><dt>Large purchases</dt><dd>${money(d.oneOff)}</dd></div><div><dt>Recurring</dt><dd>${money(d.subscriptions)}</dd></div><div><dt>Bills</dt><dd>${money(d.bills||0)}</dd></div></dl></details>`).join('')}</div></section><section id="spending-large" data-workspace-panel="spending:large" data-workspace-essential class="content-panel insights-section"><h2>Large and occasional costs</h2><p>These purchases remain part of recorded spending. They are excluded from the routine baseline, not assumed never to happen again.</p><div class="table-scroll"><table class="ledger-table"><thead><tr><th>Date</th><th>Purchase</th><th>Amount</th><th>Why separate</th></tr></thead><tbody>${e.oneOffs.map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.group)} · ${esc(r.description)}</td><td>${money(r.amount)}</td><td>${esc(r.reason)}</td></tr>`).join('')}</tbody></table></div><details id="routine-methodology"><summary>How the routine estimate is calculated</summary><p>With at least ${e.outlierMethod.minimumPurchases} variable purchases, separate purchases strictly above ${money(e.oneOffThreshold??e.outlierMethod.floor)}. Rule: ${esc(e.outlierMethod.rule)} Confirmed bills, transfers and recurring charges are handled separately. Sparse history does not support a reliable large-purchase threshold.</p><p>Raw spending average: ${money(e.rawDaily)}/day. Routine estimate: ${money(e.daily)}/day. Neither measures unrecorded cash purchases.</p></details></section><section id="spending-opportunities" data-workspace-panel="spending:opportunities" data-workspace-essential class="content-panel insights-section">${savings(e)}</section>`;
    bind(content,e);
  }
  return {renderForecast,renderSpending,renderDetail:details.render};
}
